Part.Source:
// Buscando os dados da Prefeitura for each trnsprefeituras where prefCodigo = &prefCodigo &prefLogo = prefLogo &prefNome = prefNome endfor
// Buscando o grupo do cardápio for each trnscardapio order prefCodigo, carDapCodigo where prefCodigo = &prefCodigo where carDapCodigo = &carDapCodigo &Titulo = 'Cardápio : ' + carDapDescricao.Trim() + ' | Área ( Etapa ) : ' &carDapGruCodigo = carDapGruCodigo &usuCodigo = carDapNutricionista endFor
// Buscando a Área e Etapa &areaNome = '' &etapaNome = '' if &prefCodigo<>26 for each Atendimento order prefCodigo, carGruCodigo, AreEnsNome, AreEnsEtapaNome where prefCodigo = &prefCodigo where carGruCodigo = &carDapGruCodigo when &prefCodigo<>26 if &areaNome <> AreEnsNome OR &etapaNome <> AreEnsEtapaNome &Titulo += AreEnsNome.Trim() + ' ( '+ AreEnsEtapaNome.Trim() + ' ) - ' endif &areaNome = AreEnsNome &etapaNome = AreEnsEtapaNome endfor endif
// Verificando dados da unidade &locCodigo2 =0 if &locCodigo<>0 &SubTitulo = '' for each Atendimento order prefCodigo, carGruCodigo, locCodigo where prefCodigo = &prefCodigo where carGruCodigo = &carDapGruCodigo where locCodigo = &locCodigo for each trnslocal where prefCodigo = &prefCodigo where locCodigo = &locCodigo &SubTitulo = 'Unidade Educativa : ' + locDescricao Do 'ImprimirCardapio' endfor exit when none // print printCabecalho print printSemDados endfor else if &opcNomeEscola = 'S' &SubTitulo = '' for each Atendimento order prefCodigo, carGruCodigo, locCodigo where prefCodigo = &prefCodigo where carGruCodigo = &carDapGruCodigo &locCodigo2 = locCodigo for each trnslocal where prefCodigo = &prefCodigo where locCodigo = &locCodigo2 &SubTitulo = 'Unidade Educativa : ' + locDescricao Do 'ImprimirCardapio' endfor endfor else Do 'ImprimirCardapio' endif endif
// Rotina de impressão do Cardápio Sub 'ImprimirCardapio' Header print printCabecalho
if &printCabDetalhes print printCabecalhoDetalhes endif
if &printTurno // print printTurno endif
if &printReceita print printLinha print printCabIngredientes endif End
&printReceita = false
&dataInicial = ymdtod(&carDapMesAno.Year(),&carDapMesAno.Month(),1) &dataFinal = &dataInicial.EndOfMonth()
&Semana = CalculaSemana(&dataInicial) // &Semana = &opcSemanaINI // &dataInicial = PRCDCalculaDiaUtilSemana( &carDapMesAno.Month(),&carDapMesAno.Year(),&Semana)
&carPratoData = &dataInicial &DifDias = (7 - &dataInicial.DayOfWeek())
do while &carPratoData <= &dataFinal
// Define período da semana &carPratoDataIni = &carPratoData &carPratoDataFim = &carPratoData.AddDays(&DifDias) if &carPratoDataFim > &dataFinal &carPratoDataFim = &dataFinal endif
// Monta cabeçalho do detalhe &printCabDetalhes = false &CabDetalhes() = '' &CabDetalhes(1) = format('%1ª Semana',&Semana.ToString()) for &DataCab = &carPratoDataIni to &carPratoDataFim &CabDetalhes(dow(&DataCab) + 1) = format('%1/%2 (%3)',&DataCab.Day().ToString().Trim(),&DataCab.MonthName().Substring(1,3),&DataCab.DayOfWeekName().Substring(1,3)) endfor
// Imprime linha de detalhes &carPratoTurnoPeriodo = 'X' &carPratoHorario.SetEmpty() &DadosDetalhes() = '' &MatrizDetalhes() = '' &LinhaMaxima = 0
for each trnscardapioprato, trnsrefeicaotipo, trnspratos order prefCodigo, carDapCodigo,carPratoTurnoHorario,carPratoData where prefCodigo = &prefCodigo where carDapCodigo = &carDapCodigo Where carPratoData >= &carPratoDataIni where carPratoData <= &carPratoDataFim where pratoCodigo = carPratoRefeicao
if not &printCabDetalhes and &Semana>=&opcSemanaINI and &Semana<=&opcSemanaFIN print printCabecalhoDetalhes &printCabDetalhes = true endif
// Verifica quebra de turno if &carPratoTurnoPeriodo <> carPratoTurnoPeriodo if &DadosDetalhes(1) <> '' Do 'ImprimeDados' endif
&carPratoTurnoPeriodo = carPratoTurnoPeriodo &carPratoTurnoNome = carPratoTurnoNome endif
// Verifica quebra de horário if &carPratoHorario <> carPratoTurnoHorario Do 'ImprimeDados' &carPratoHorario = carPratoTurnoHorario &DadosDetalhes(1) = carPratoTurnoHorario.ToFormattedString() + ' - ' + carPratoTurnoNome endif
&Coluna = dow(carPratoData) for &Linha = 1 to 20 if &MatrizDetalhes(&Linha,&Coluna) = '' &MatrizDetalhes(&Linha,&Coluna) = pratoDscricao
if &Linha > &LinhaMaxima &LinhaMaxima = &Linha endif
exit else &MatrizDetalhes(&Linha,&Coluna) = &MatrizDetalhes(&Linha,&Coluna) + chr(13) + pratoDscricao
if &Linha > &LinhaMaxima &LinhaMaxima = &Linha endif
exit endif endfor endfor
if &DadosDetalhes(1) <> '' and &Semana>=&opcSemanaINI and &Semana<=&opcSemanaFIN Do 'ImprimeDados' else exit endif
&carPratoData = &carPratoDataFim + 1 &Semana += 1 &DifDias = 6 enddo
if not &usuCodigo.IsEmpty() Do 'ImprimeNutricionistas' endif
// Impressão das Receitas if &opcReceita = 'S' Eject &Titulo = 'Receitas' &printTurno = false &SubTitulo = '' //&strPratos = ''
For each trnscardapioprato unique carPratoRefeicao where prefCodigo = &prefCodigo where carDapCodigo = &carDapCodigo &pratoCodigo = carPratoRefeicao // &pratoCodigo = carPratoCodigo Do 'ImprimeReceita' EndFor endif Eject endSub
// Rotina de impressão de dados Sub 'ImprimeDados' if &DadosDetalhes(1) <> '' for &Linha = 1 to &LinhaMaxima &DadosDetalhes(2) = &MatrizDetalhes(&Linha,1) &DadosDetalhes(3) = &MatrizDetalhes(&Linha,2) &DadosDetalhes(4) = &MatrizDetalhes(&Linha,3) &DadosDetalhes(5) = &MatrizDetalhes(&Linha,4) &DadosDetalhes(6) = &MatrizDetalhes(&Linha,5) &DadosDetalhes(7) = &MatrizDetalhes(&Linha,6) &DadosDetalhes(8) = &MatrizDetalhes(&Linha,7) print printDetalhesDados
&DadosDetalhes() = '' endfor
// print printLinha &MatrizDetalhes() = '' &LinhaMaxima = 0 endif EndSub
// Rotina de impressão das receitas Sub 'ImprimeReceita' // apuração de refeições do cardápo &printCabDetalhes = false
For each trnspratos where prefCodigo = &prefCodigo where pratoCodigo = &pratoCodigo // if strSearch(&strPratos, &pratoCodigo.ToString().Trim() ) = 0
&pratoModoDeFazer = pratoModoDeFazer &pratoDscricao = pratoDscricao.Trim()
/* + ' | Prefeitura :' + &prefCodigo.toString() + ' | Prato : ' + &pratoCodigo.toString() + ' | Prato Atual : ' + pratoCodigo.toString() */
if pratoComFreezer = 'S' &usaFreezerr = 'Sim' else &usaFreezerr = 'Não' endif
if pratoForno = 'S' &usaForno = 'Sim' else &usaForno = 'Não' endif
if pratoRepeticao = 'S' &repete = 'Sim' else &repete = 'Não' endif
&printReceita = false print printDadosReceita print printCabIngredientes &printReceita = true
// apuração de ingredientes For each trnspratosingredientes where prefCodigo = &prefCodigo where pratoCodigo = &pratoCodigo &pratIngrProdCodigo = pratIngrProdCodigo
For each trnsprodutos where prodCodigo = &pratIngrProdCodigo where prefCodigo = &prefCodigo &prodDescricao = prodDescricao For each trnsunidades where prefCodigo = &prefCodigo where uniCodigo = prodUnidMedConsumo &uniDescricao = uniDescricao endFor EndFor print printIngredientes EndFor
/* &strPratos =&strPratos+ '['+ &pratoCodigo.ToString().Trim() +']' endif*/ EndFor EndSub
// Rotina de impressão das nutricionistas Sub 'ImprimeNutricionistas'
for each where usuCodigo = &usuCodigo where prefCodigo = &prefCodigo
if usuStatus = 'A' Do Case Case &usuNome.IsEmpty() &usuNome = usuNome &usuAssinatura = usuAssinatura &usuinscricao = usuInscricao /* Case &usuNome1.IsEmpty() and &usuNome<>usuNome &usuNome1 = usuNome &usuAssinatura1 = usuAssinatura &usuinscricao1 = usuInscricao Case &usuNome2.IsEmpty() and &usuNome1<>usuNome &usuNome2 = usuNome &usuAssinatura2 = usuAssinatura &usuinscricao2 = usuInscricao Case &usuNome3.IsEmpty() and &usuNome2<>usuNome &usuNome3 = usuNome &usuAssinatura3 = usuAssinatura &usuinscricao3 = usuInscricao */ endCase endif endFor
if not &usuNome.IsEmpty() print printDadosNutricionista endif
endSub
